package com.mavric.health.persistence.sqlserver;
import java.util.*;
import java.util.function.Supplier;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.ApiException;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Offline contracts and modeled transactions, not hospital occupancy or clinical integrity evidence. */
public class SqlServerHospitalStoreTest {
 public static final String ACTOR="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",ID="cc000000-0000-4000-8000-000000000001",OTHER="dd000000-0000-4000-8000-000000000001",DATE="2026-11-05T00:00:00.123456Z";
 public static Map<String,Object> resource(){var row=new LinkedHashMap<String,Object>();row.put("id",ID);row.put("tenantId",TENANT);row.put("branchId",OTHER);row.put("name","Synthetic \u4e2d\ud83e\uddb7");row.put("kind","BED");row.put("active",true);row.put("occupied",false);return row;}
 public static Map<String,Object> admission(){var row=new LinkedHashMap<String,Object>();row.put("id",ID);row.put("tenantId",TENANT);row.put("patientId",OTHER);row.put("resourceId",OTHER);row.put("status","ADMITTED");row.put("reason","Synthetic \u4e2d\ud83e\uddb7");row.put("revision",1);row.put("admittedAt",DATE);row.put("dischargedAt",null);row.put("occupiedResource",OTHER);row.put("admittedPatient",OTHER);return row;}
 public static class Fixture {
  public final SqlServerExecutor executor=mock(SqlServerExecutor.class);public final ModelTransactionManager manager=new ModelTransactionManager();public final SqlServerHospitalStore store=new SqlServerHospitalStore(executor,manager);public final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/hospital/resources");public Actor actor;public final List<SqlServerProcedure> calls=new ArrayList<>();public final List<SqlServerContext> contexts=new ArrayList<>();public final List<Map<String,Object>> resources=new ArrayList<>(),admissions=new ArrayList<>();public final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();
  public Fixture(){actor("AUD");when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ACTOR,c.actorId());assertEquals(TENANT,c.tenantId());assertEquals("a".repeat(64),c.tokenHash());assertEquals(0,((Object[])inv.getRawArguments()[2]).length);var sp=inv.<SqlServerProcedure>getArgument(0);calls.add(sp);contexts.add(c);manager.events.add("sp:"+sp.name());return results.isEmpty()?new SqlServerExecutor.Result(List.of(switch(sp){case HOSPITAL_RESOURCES->resources;case HOSPITAL_ADMISSIONS->admissions;default->throw new AssertionError("Unexpected descriptor");}),List.of()):results.removeFirst();});}
  public void actor(String role){actor=new Actor(ACTOR,"Synthetic","synthetic@example.test",TENANT,List.of(role),"a".repeat(64));request.setAttribute("health.actor",actor);request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("HOSPITAL")));request.setAttribute("health.requestId",OTHER);}
 }
 final Fixture f=new Fixture();
 @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static ApiException safe(Runnable work){var e=assertThrows(ApiException.class,work::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());assertFalse(e.toString().contains("private-canary"));return e;}
 @Test void twoZeroArgumentDescriptorsExactProjectionsAndPrivateColumnsOmitted(){var r=resource();r.put("private","private-canary");var a=admission();a.put("private","private-canary");f.resources.add(r);f.admissions.add(a);var resources=f.store.resources(f.request);var admissions=f.store.admissions(f.request);assertEquals(7,resources.getFirst().size());assertEquals(11,admissions.getFirst().size());assertFalse(resources.toString().contains("private-canary"));assertFalse(admissions.toString().contains("private-canary"));assertEquals(List.of(SqlServerProcedure.HOSPITAL_RESOURCES,SqlServerProcedure.HOSPITAL_ADMISSIONS),f.calls);assertThrows(UnsupportedOperationException.class,resources::clear);assertThrows(UnsupportedOperationException.class,()->admissions.getFirst().put("revision",2));assertThrows(UnsupportedOperationException.class,()->resources.getFirst().clear());assertNull(admissions.getFirst().get("dischargedAt"));}
 @Test void empty200And201RowsOrderPreservedForBothReads(){for(boolean admissions:List.of(false,true)){var source=admissions?f.admissions:f.resources;Supplier<List<Map<String,Object>>> work=admissions?()->f.store.admissions(f.request):()->f.store.resources(f.request);assertTrue(work.get().isEmpty());for(int i=0;i<200;i++){var row=admissions?admission():resource();row.put("id",UUID.nameUUIDFromBytes(("synthetic-"+(200-i)).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString());source.add(row);}var result=work.get();assertEquals(source,result);source.getFirst().put("private","mutated");assertFalse(result.getFirst().containsKey("private"));source.add(admissions?admission():resource());safe(work::get);}}
 @Test void resourceBitAndKindsPreserveInactiveOccupiedAndDomainNeutralReads(){for(String domain:List.of("HUMAN","ANIMAL"))for(String kind:List.of("BED","CAGE"))for(boolean active:List.of(false,true))for(boolean occupied:List.of(false,true)){f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","synthetic","VETERINARY",domain,"SUSPENDED",List.of("HOSPITAL")));var row=resource();row.put("kind",kind);row.put("active",active);row.put("occupied",occupied);f.resources.clear();f.resources.add(row);assertEquals(row,f.store.resources(f.request).getFirst());}}
 @Test void admissionNullableComputedColumnsAndMaximumRevisionTextArePreserved(){var row=admission();row.put("revision",Integer.MAX_VALUE);row.put("reason","\ud83e\uddb7".repeat(500));row.put("status","DISCHARGED");row.put("dischargedAt",DATE);row.put("occupiedResource",null);row.put("admittedPatient",null);f.admissions.add(row);assertEquals(row,f.store.admissions(f.request).getFirst());row.put("dischargedAt",null);assertEquals(row,f.store.admissions(f.request).getFirst());}
 @Test void everyMissingOrNullRequiredColumnAndIncorrectTypeFailsInsideTransaction(){for(boolean admissions:List.of(false,true)){var source=admissions?f.admissions:f.resources;Runnable work=admissions?()->f.store.admissions(f.request):()->f.store.resources(f.request);var good=admissions?admission():resource();for(String key:good.keySet()){var row=new LinkedHashMap<>(good);row.remove(key);source.clear();source.add(row);safe(work);assertEquals("rollback",f.manager.events.getLast());row=new LinkedHashMap<>(good);row.put(key,new Object());source.clear();source.add(row);safe(work);if(!Set.of("dischargedAt","occupiedResource","admittedPatient").contains(key)){row=new LinkedHashMap<>(good);row.put(key,null);source.clear();source.add(row);safe(work);}}}}
 @Test void malformedResourceValuesRejectedWithoutFiltering(){for(var bad:List.of(Map.entry("tenantId",OTHER),Map.entry("id","bad"),Map.entry("branchId","CC000000-0000-4000-8000-000000000001"),Map.entry("name","a".repeat(101)),Map.entry("kind","ROOM"),Map.entry("active",1),Map.entry("occupied","true"))){var row=resource();row.put(bad.getKey(),bad.getValue());f.resources.clear();f.resources.add(row);safe(()->f.store.resources(f.request));}}
 @Test void malformedAdmissionRevisionStatusComputedAndIdsRejected(){for(var bad:List.of(Map.entry("tenantId",OTHER),Map.entry("patientId","bad"),Map.entry("resourceId","bad"),Map.entry("reason","a".repeat(1001)),Map.entry("revision",0),Map.entry("revision",1L),Map.entry("status","PENDING"),Map.entry("occupiedResource",ID),Map.entry("admittedPatient",ID))){var row=admission();row.put(bad.getKey(),bad.getValue());f.admissions.clear();f.admissions.add(row);safe(()->f.store.admissions(f.request));}var row=admission();row.put("status","DISCHARGED");f.admissions.clear();f.admissions.add(row);safe(()->f.store.admissions(f.request));}
 @Test void timestampUtcMicroAndSqlBoundsValidatedIncludingNullable(){for(String key:List.of("admittedAt","dischargedAt")){for(String valid:List.of("0001-01-01T00:00:00Z",DATE,"9999-12-31T23:59:59.999999Z")){var row=admission();row.put(key,valid);f.admissions.clear();f.admissions.add(row);assertEquals(valid,f.store.admissions(f.request).getFirst().get(key));}for(String invalid:List.of("bad","2026-11-05T00:00:00+00:00","2026-11-05T00:00:00.123456789Z","0000-01-01T00:00:00Z","+10000-01-01T00:00:00Z")){var row=admission();row.put(key,invalid);f.admissions.clear();f.admissions.add(row);safe(()->f.store.admissions(f.request));}}}
 @Test void exactOneResultsetRequiredAndNoFakeEmptyFallback(){for(var result:List.of(new SqlServerExecutor.Result(List.of(),List.of()),new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()))){f.results.add(result);safe(()->f.store.resources(f.request));f.results.add(result);safe(()->f.store.admissions(f.request));}doReturn(null).when(f.executor).execute(any(),any(),any(Object[].class));safe(()->f.store.resources(f.request));}
 @Test void directRoleMatrixModuleAndReadWithoutWriteStatusGate(){for(String role:List.of("ADM","PRO","ASI","AUD","REC","PAC","SAD","SOP")){f.actor(role);if(Set.of("ADM","PRO","ASI","AUD").contains(role))f.store.resources(f.request);else assertEquals(403,assertThrows(ApiException.class,()->f.store.resources(f.request)).status);if(Set.of("PRO","ASI","AUD").contains(role))f.store.admissions(f.request);else assertEquals(403,assertThrows(ApiException.class,()->f.store.admissions(f.request)).status);}f.actor("AUD");f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","CANCELLED",List.of("HOSPITAL")));f.store.admissions(f.request);f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));assertEquals("MODULE_NOT_INCLUDED",assertThrows(ApiException.class,()->f.store.resources(f.request)).code);}
 @Test void directInternalContextErrorsNeverCallExecutor(){safe(()->f.store.resources(null));f.request.setAttribute("health.tenant","forged");safe(()->f.store.resources(f.request));f.actor("AUD");f.request.setAttribute("health.actor",new Actor(ACTOR,"Synthetic","synthetic@example.test",OTHER,List.of("AUD"),"a".repeat(64)));assertEquals(403,assertThrows(ApiException.class,()->f.store.resources(f.request)).status);f.actor("AUD");f.request.setAttribute("health.actor",null);assertEquals(403,assertThrows(ApiException.class,()->f.store.admissions(f.request)).status);for(String token:List.of("bad","a".repeat(63))){f.actor("AUD");f.request.setAttribute("health.actor",new Actor(ACTOR,"Synthetic","synthetic@example.test",TENANT,List.of("AUD"),token));safe(()->f.store.resources(f.request));}f.actor("AUD");f.request.setAttribute("health.actor",new Actor("bad","Synthetic","synthetic@example.test",TENANT,List.of("AUD"),"a".repeat(64)));safe(()->f.store.resources(f.request));f.actor("AUD");f.request.setAttribute("health.requestId",new Object());safe(()->f.store.resources(f.request));verifyNoInteractions(f.executor);}
 @Test void explicitRequestNotOtherThreadLocalAndCallerStatePreserved(){var foreign=new MockHttpServletRequest();TraceContext.REQUEST.set(foreign);f.request.addHeader("X-Tenant-Id",OTHER);f.request.addHeader("Authorization","private-canary");var actor=f.actor;var host=f.request.getAttribute("health.tenant");f.store.resources(f.request);assertSame(foreign,TraceContext.REQUEST.get());assertSame(actor,f.request.getAttribute("health.actor"));assertSame(host,f.request.getAttribute("health.tenant"));assertEquals(OTHER,f.contexts.getFirst().requestId());assertEquals("GET",f.contexts.getFirst().method());assertTrue(SecurityContextHolder.getContext().getAuthentication()==null);}
 @Test void requiredJoinsOuterAndCancellationAndMappingRollbackAreModeled(){f.manager.outer(()->{f.store.resources(f.request);f.store.admissions(f.request);assertFalse(f.manager.events.contains("commit"));return null;});assertEquals(1,Collections.frequency(f.manager.events,"begin:0"));assertEquals(1,Collections.frequency(f.manager.events,"commit"));assertThrows(RuntimeException.class,()->f.manager.outer(()->{f.store.resources(f.request);throw new RuntimeException("cancel");}));assertEquals("rollback",f.manager.events.getLast());f.admissions.add(new LinkedHashMap<>());safe(()->f.manager.outer(()->f.store.admissions(f.request)));assertEquals("rollback",f.manager.events.getLast());}
 @Test void commitFailureAndVendorErrorsSafeWithoutRetry(){f.manager.failCommit=true;safe(()->f.store.resources(f.request));for(int vendor:List.of(51000,51001,51002,51003,51004,51005,99999)){clearInvocations(f.executor);doThrow(new RuntimeException(new java.sql.SQLException("private-canary",null,vendor))).when(f.executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->f.store.admissions(f.request));assertEquals(switch(vendor){case 51000->400;case 51001,51004->403;case 51002->404;case 51003,51005->409;default->500;},e.status);assertNull(e.getCause());assertFalse(e.toString().contains("private-canary"));verify(f.executor,times(1)).execute(eq(SqlServerProcedure.HOSPITAL_ADMISSIONS),any(),any(Object[].class));assertEquals("rollback",f.manager.events.getLast());}assertEquals("SqlServerHospitalStore[redacted]",f.store.toString());}
}
